class Main {public static void main(String[] args){var in=new java.util.Scanner(System.in);int n=in.nextInt();Integer answer=null;for(int i=0;i<n;i++){int x=in.nextInt();String s=Long.toString(Math.abs((long)x));boolean ok=true;for(int d=1;d<s.length();d++)if(s.charAt(d-1)>=s.charAt(d))ok=false;if(ok&&answer==null)answer=x;}System.out.println(answer==null?"Подходящих чисел нет":answer);}}
